  Write "computing";
  r <- x * x;
EndFunction

Algorithm Main
  Write Square(3);
EndAlgorithm

Function finalPrice <- WithDiscount(price As Integer, percent As Integer)
  Define finalPrice As Integer;
  finalPrice <- price * (100 - percent) Div 100;
EndFunction

Algorithm Kiosk
  Define percent, price As Integer;
  Define total As Integer <- 0;
  Write "What discount?";
  Read percent;
  For i <- 1 To 3 Do
    Read price;
    total <- total + WithDiscount(price, percent);
  EndFor
  Write "Total: ", total;
EndAlgorithm

Function finalPrice <- WithDiscount(price As Integer, percent As Integer)
  Define finalPrice As Integer;
  finalPrice <- price * (100 - percent) Div 100;
EndFunction

Algorithm Tests
  Write WithDiscount(100, 10);
  Write WithDiscount(100, 0);
  Write WithDiscount(100, 100);
  Write WithDiscount(15, 10);
EndAlgorithm
